router.get('/functional-locations', async (req,res)=>{try{const [rows]=await pool.execute('SELECT * FROM functional_locations WHERE org_id=? ORDER BY location_code',[req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar localizações funcionais'});}});
router.post('/functional-locations', write, async (req,res)=>{const {location_code,name,parent_location_id,cost_center,work_center,status}=req.body||{};const parentId=parent_location_id===undefined||parent_location_id===null?null:Number(parent_location_id);if(!text(location_code,60)||!text(name,200)||!(parentId===null||(Number.isSafeInteger(parentId)&&parentId>0))||(status!==undefined&&!['active','inactive'].includes(status))||[cost_center,work_center].some(value=>value!==undefined&&(typeof value!=='string'||value.length>80)))return res.status(400).json({error:'Localização funcional inválida'});try{if(parentId!==null){const [parent]=await pool.execute('SELECT id FROM functional_locations WHERE id=? AND org_id=?',[parentId,req.user.org_id]);if(!parent.length)return res.status(404).json({error:'Localização pai não encontrada'});}const [r]=await pool.execute('INSERT INTO functional_locations (org_id,location_code,name,parent_location_id,cost_center,work_center,status) VALUES (?,?,?,?,?,?,?)',[req.user.org_id,location_code.trim(),name.trim(),parentId,cost_center?.trim()||null,work_center?.trim()||null,status||'active']);res.status(201).json({id:r.insertId,location_code:location_code.trim(),name:name.trim(),parent_location_id:parentId});}catch(e){res.status(e.code==='ER_DUP_ENTRY'?409:500).json({error:e.code==='ER_DUP_ENTRY'?'Código de localização já existe':'Erro ao criar localização funcional'});}});
router.get('/functional-locations/tree', async (req,res)=>{try{const [rows]=await pool.execute('SELECT id,location_code,name,parent_location_id,cost_center,work_center,status FROM functional_locations WHERE org_id=? ORDER BY location_code',[req.user.org_id]);const byParent=new Map(),roots=[];rows.forEach(row=>{row.children=[];byParent.set(row.id,row);});rows.forEach(row=>{const parent=byParent.get(row.parent_location_id);(parent?parent.children:roots).push(row);});res.json(roots);}catch(_){res.status(500).json({error:'Erro ao montar árvore de localizações'});}});
router.patch('/functional-locations/:id', requireRoles('superadmin','admin','manager'), async (req,res)=>{const id=Number(req.params.id),b=req.body||{},parentId=b.parent_location_id===undefined?undefined:(b.parent_location_id===null?null:Number(b.parent_location_id)),hasParent=parentId!==undefined?1:0;if(!Number.isSafeInteger(id)||id<1||(b.name!==undefined&&!text(b.name,200))||(b.status!==undefined&&!['active','inactive'].includes(b.status))||[b.cost_center,b.work_center].some(value=>value!==undefined&&(typeof value!=='string'||value.length>80))||(parentId!==undefined&&parentId!==null&&(!Number.isSafeInteger(parentId)||parentId<1||parentId===id)))return res.status(400).json({error:'Atualização de localização inválida'});try{if(parentId!==undefined&&parentId!==null){const [parents]=await pool.execute('SELECT id FROM functional_locations WHERE id=? AND org_id=?',[parentId,req.user.org_id]);if(!parents.length)return res.status(404).json({error:'Localização pai não encontrada'});const [cycles]=await pool.execute('WITH RECURSIVE descendants AS (SELECT id FROM functional_locations WHERE parent_location_id=? AND org_id=? UNION ALL SELECT f.id FROM functional_locations f JOIN descendants d ON f.parent_location_id=d.id WHERE f.org_id=?) SELECT id FROM descendants WHERE id=?',[id,req.user.org_id,req.user.org_id,parentId]);if(cycles.length)return res.status(409).json({error:'Localização pai criaria ciclo'});}const [updated]=await pool.execute('UPDATE functional_locations SET name=COALESCE(?,name),parent_location_id=CASE WHEN ?=1 THEN ? ELSE parent_location_id END,cost_center=CASE WHEN ?=1 THEN ? ELSE cost_center END,work_center=CASE WHEN ?=1 THEN ? ELSE work_center END,status=COALESCE(?,status) WHERE id=? AND org_id=?',[b.name?.trim()||null,hasParent,parentId??null,b.cost_center===undefined?0:1,b.cost_center?.trim()||null,b.work_center===undefined?0:1,b.work_center?.trim()||null,b.status||null,id,req.user.org_id]);if(!updated.affectedRows)return res.status(404).json({error:'Localização não encontrada'});res.json({id});}catch(_){res.status(500).json({error:'Erro ao atualizar localização'});}});

