router.post('/assets', write, async (req, res) => {
  const { asset_code, name, asset_type, status, location, functional_location, functional_location_id, equipment_model_id, manufacturer, model, serial_number, criticality, metadata, parent_asset_id } = req.body || {};
  if (!text(asset_code, 40) || !text(name, 200)) return res.status(400).json({ error: 'Código e nome são obrigatórios' });
  if (metadata !== undefined && (metadata === null || typeof metadata !== 'object' || Array.isArray(metadata))) return res.status(400).json({ error: 'Metadados inválidos' });
  try {
    const parentId = parent_asset_id === undefined || parent_asset_id === null ? null : Number(parent_asset_id);
    if (parentId !== null && (!Number.isSafeInteger(parentId) || parentId < 1)) return res.status(400).json({ error: 'Ativo pai inválido' });
    const functionalLocationId = functional_location_id === undefined || functional_location_id === null ? null : Number(functional_location_id);
    if (functionalLocationId !== null && (!Number.isSafeInteger(functionalLocationId) || functionalLocationId < 1)) return res.status(400).json({ error: 'Localização funcional inválida' });
    const equipmentModelId = equipment_model_id === undefined || equipment_model_id === null ? null : Number(equipment_model_id);
    if (equipmentModelId !== null && (!Number.isSafeInteger(equipmentModelId) || equipmentModelId < 1)) return res.status(400).json({ error: 'Modelo técnico inválido' });
    if (parentId !== null) { const [parent] = await pool.execute('SELECT id FROM assets WHERE id = ? AND org_id = ?', [parentId, req.user.org_id]); if (!parent.length) return res.status(404).json({ error: 'Ativo pai não encontrado' }); }
    if (functionalLocationId !== null) { const [locationRow] = await pool.execute('SELECT id FROM functional_locations WHERE id = ? AND org_id = ?', [functionalLocationId, req.user.org_id]); if (!locationRow.length) return res.status(404).json({ error: 'Localização funcional não encontrada' }); }
    if (equipmentModelId !== null) { const [modelRow] = await pool.execute('SELECT id FROM equipment_models WHERE id=? AND org_id=?', [equipmentModelId, req.user.org_id]); if (!modelRow.length) return res.status(404).json({ error: 'Modelo técnico não encontrado' }); }
    const [r] = await pool.execute('INSERT INTO assets (org_id, asset_code, name, asset_type, status, location, functional_location, functional_location_id, equipment_model_id, manufacturer, model, serial_number, criticality, metadata, parent_asset_id, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)', [req.user.org_id, asset_code.trim(), name.trim(), text(asset_type,80) ? asset_type : 'equipment', enumValue(status,['active','inactive','maintenance','retired'],'active'), text(location,120)?location:null, text(functional_location,120)?functional_location:null, functionalLocationId, equipmentModelId, text(manufacturer,120)?manufacturer:null, text(model,120)?model:null, text(serial_number,120)?serial_number:null, enumValue(criticality,['low','medium','high','critical'],'medium'), metadata === undefined ? null : JSON.stringify(metadata), parentId, req.user.id]);
    res.status(201).json({ id: r.insertId, asset_code: asset_code.trim(), name: name.trim() });
  } catch (e) { res.status(e.code === 'ER_DUP_ENTRY' ? 409 : 500).json({ error: e.code === 'ER_DUP_ENTRY' ? 'Código de ativo já existe' : 'Erro ao criar ativo' }); }
});
router.patch('/assets/:id', write, async (req,res)=>{
  const id=Number(req.params.id),b=req.body||{};
  const lengths={name:200,manufacturer:120,model:120,serial_number:120,location:120,description:5000};
  if(!Number.isSafeInteger(id)||id<1||!text(b.name,200)||!['active','inactive','maintenance','retired'].includes(b.status)||!['low','medium','high','critical'].includes(b.criticality)||Object.entries(lengths).some(([key,max])=>b[key]!==undefined&&(typeof b[key]!=='string'||b[key].length>max))||b.metadata!==undefined&&(b.metadata===null||typeof b.metadata!=='object'||Array.isArray(b.metadata)))return res.status(400).json({error:'Dados do ativo inválidos'});
  const locationId=b.functional_location_id==null?null:Number(b.functional_location_id),modelId=b.equipment_model_id==null?null:Number(b.equipment_model_id),parentId=b.parent_asset_id==null?null:Number(b.parent_asset_id);
  if([locationId,modelId,parentId].some(value=>value!==null&&(!Number.isSafeInteger(value)||value<1))||parentId===id)return res.status(400).json({error:'Vínculo do ativo inválido'});
  try{
    if(locationId!==null){const [rows]=await pool.execute('SELECT id FROM functional_locations WHERE id=? AND org_id=?',[locationId,req.user.org_id]);if(!rows.length)return res.status(404).json({error:'Localização funcional não encontrada'});}
    if(modelId!==null){const [rows]=await pool.execute('SELECT id FROM equipment_models WHERE id=? AND org_id=?',[modelId,req.user.org_id]);if(!rows.length)return res.status(404).json({error:'Modelo técnico não encontrado'});}
    if(parentId!==null){const [parents]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[parentId,req.user.org_id]);if(!parents.length)return res.status(404).json({error:'Ativo pai não encontrado'});const [cycles]=await pool.execute('WITH RECURSIVE descendants AS (SELECT id FROM assets WHERE parent_asset_id=? AND org_id=? UNION ALL SELECT a.id FROM assets a JOIN descendants d ON a.parent_asset_id=d.id WHERE a.org_id=?) SELECT id FROM descendants WHERE id=? LIMIT 1',[id,req.user.org_id,req.user.org_id,parentId]);if(cycles.length)return res.status(409).json({error:'A operação criaria um ciclo na hierarquia'});}
    const metadataJson=b.metadata===undefined?null:JSON.stringify(b.metadata);
    if(metadataJson&&metadataJson.length>16000)return res.status(400).json({error:'Metadados do ativo excedem o limite'});
    const [updated]=await pool.execute('UPDATE assets SET name=?,status=?,criticality=?,manufacturer=?,model=?,serial_number=?,location=?,description=?,functional_location_id=?,equipment_model_id=?,parent_asset_id=?,metadata=CASE WHEN ?=1 THEN ? ELSE metadata END WHERE id=? AND org_id=?',[b.name.trim(),b.status,b.criticality,b.manufacturer?.trim()||null,b.model?.trim()||null,b.serial_number?.trim()||null,b.location?.trim()||null,b.description?.trim()||null,locationId,modelId,parentId,b.metadata===undefined?0:1,metadataJson,id,req.user.org_id]);
    if(!updated.affectedRows)return res.status(404).json({error:'Ativo não encontrado'});
    res.json({id});
  }catch(_){res.status(500).json({error:'Erro ao atualizar ativo'});}
});
router.patch('/assets/:id/spatial', write, async (req,res)=>{const id=Number(req.params.id),b=req.body||{},values=['x','y','z','rotation'].map(key=>b[key]===undefined?null:Number(b[key]));if(!Number.isSafeInteger(id)||id<1||values.some(value=>value!==null&&(!Number.isFinite(value)||Math.abs(value)>1000000))||(b.level!==undefined&&!text(b.level,80)))return res.status(400).json({error:'Posição espacial inválida'});try{const [updated]=await pool.execute('UPDATE assets SET spatial_x=COALESCE(?,spatial_x),spatial_y=COALESCE(?,spatial_y),spatial_z=COALESCE(?,spatial_z),spatial_rotation=COALESCE(?,spatial_rotation),spatial_level=COALESCE(?,spatial_level) WHERE id=? AND org_id=?', [...values,text(b.level,80)?b.level.trim():null,id,req.user.org_id]);if(!updated.affectedRows)return res.status(404).json({error:'Ativo não encontrado'});res.json({id});}catch(_){res.status(500).json({error:'Erro ao atualizar posição espacial'});}});
router.patch('/assets/:id/parent', write, async (req,res)=>{
  const assetId=Number(req.params.id), parentId=req.body?.parent_asset_id === null ? null : Number(req.body?.parent_asset_id);
  if(!Number.isSafeInteger(assetId)||assetId<1||!(parentId===null||(Number.isSafeInteger(parentId)&&parentId>0))||assetId===parentId)return res.status(400).json({error:'Hierarquia inválida'});
  try { const [asset]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);if(!asset.length)return res.status(404).json({error:'Ativo não encontrado'}); if(parentId!==null){const [parent]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[parentId,req.user.org_id]);if(!parent.length)return res.status(404).json({error:'Ativo pai não encontrado'}); const [cycle]=await pool.execute('WITH RECURSIVE ancestors AS (SELECT id,parent_asset_id FROM assets WHERE id=? AND org_id=? UNION ALL SELECT a.id,a.parent_asset_id FROM assets a JOIN ancestors x ON a.id=x.parent_asset_id WHERE a.org_id=?) SELECT id FROM ancestors WHERE id=? LIMIT 1',[parentId,req.user.org_id,req.user.org_id,assetId]);if(cycle.length)return res.status(409).json({error:'A operação criaria um ciclo na hierarquia'});}await pool.execute('UPDATE assets SET parent_asset_id=? WHERE id=? AND org_id=?',[parentId,assetId,req.user.org_id]);res.json({id:assetId,parent_asset_id:parentId});}catch(_){res.status(500).json({error:'Erro ao atualizar hierarquia'});}
});
