router.post('/work-orders', write, async (req, res) => {
  const { asset_id, title, description, type, priority, due_at, assigned_to } = req.body || {};
  if (!Number.isSafeInteger(asset_id) || asset_id < 1 || !text(title, 200)) return res.status(400).json({ error: 'Ativo e título são obrigatórios' });
  try {
    const [asset] = await pool.execute('SELECT id FROM assets WHERE id = ? AND org_id = ?', [asset_id, req.user.org_id]);
    if (!asset.length) return res.status(404).json({ error: 'Ativo não encontrado' });
    const [r] = await pool.execute('INSERT INTO maintenance_work_orders (org_id, asset_id, title, description, type, priority, due_at, assigned_to, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)', [req.user.org_id, asset_id, title.trim(), text(description,5000)?description:null, enumValue(type,['preventive','corrective','inspection'],'corrective'), enumValue(priority,['low','medium','high','critical'],'medium'), due_at || null, Number.isSafeInteger(assigned_to) ? assigned_to : null, req.user.id]);
    const workOrderNumber=`OS-${String(r.insertId).padStart(8,'0')}`; await pool.execute('UPDATE maintenance_work_orders SET work_order_number=? WHERE id=? AND org_id=?',[workOrderNumber,r.insertId,req.user.org_id]); await pool.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,actor_id) VALUES (?,?,?,?)',[req.user.org_id,r.insertId,'created',req.user.id]);
    res.status(201).json({ id: r.insertId, work_order_number: workOrderNumber, asset_id, title: title.trim(), status: 'open' });
  } catch (_) { res.status(500).json({ error: 'Erro ao criar ordem de manutenção' }); }
});
router.post('/work-orders/:id/release', requireRoles('superadmin','admin','manager'), async(req,res)=>{
  const id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Ordem inválida'});
  const connection=await pool.getConnection();
  try{await connection.beginTransaction();const [rows]=await connection.execute('SELECT status,released_at FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[id,req.user.org_id]);if(!rows.length){await connection.rollback();return res.status(404).json({error:'Ordem não encontrada'});}if(rows[0].status!=='open'||rows[0].released_at){await connection.rollback();return res.status(409).json({error:'Somente uma ordem aberta pode ser liberada'});}await connection.execute('UPDATE maintenance_work_orders SET released_at=NOW(),released_by=? WHERE id=? AND org_id=?',[req.user.id,id,req.user.org_id]);await connection.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,actor_id) VALUES (?,?,?,?)',[req.user.org_id,id,'released',req.user.id]);await connection.commit();res.json({id,released:true});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao liberar ordem'});}finally{connection.release();}
});
router.patch('/work-orders/:id/status', write, async (req, res) => {
  const id=Number(req.params.id), status=req.body?.status;
  const allowed=['open','in_progress','blocked','waiting_materials','paused','completed','cancelled'];
  if(['waiting_materials','paused','cancelled'].includes(status)&&!text(req.body?.reason,300))return res.status(400).json({error:'Informe o motivo da transição'});
  if(!Number.isSafeInteger(id)||id<1||!allowed.includes(status)) return res.status(400).json({error:'Status inválido'});
  const connection=await pool.getConnection();
  try {await connection.beginTransaction();
    const [rows]=await connection.execute('SELECT status,released_at FROM maintenance_work_orders WHERE id = ? AND org_id = ? FOR UPDATE', [id, req.user.org_id]);
    if(!rows.length){await connection.rollback();return res.status(404).json({error:'Ordem não encontrada'});}
    const current=rows[0].status;
    const transitions={open:['in_progress','cancelled'],in_progress:['blocked','waiting_materials','paused','completed'],blocked:['in_progress','waiting_materials','cancelled'],waiting_materials:['in_progress','cancelled'],paused:['in_progress','cancelled'],completed:[],cancelled:[]};
    if(!transitions[current]?.includes(status)){await connection.rollback();return res.status(409).json({error:'Transição de status inválida'});}
    if(status==='in_progress'&&!rows[0].released_at){await connection.rollback();return res.status(409).json({error:'Libere formalmente a ordem antes de iniciar'});}
    if(status==='completed'){const [tasks]=await connection.execute('SELECT COUNT(*) AS pending FROM work_order_tasks WHERE work_order_id=? AND org_id=? AND is_completed=0',[id,req.user.org_id]);if(Number(tasks[0].pending)>0){await connection.rollback();return res.status(409).json({error:'Conclua as tarefas pendentes antes de encerrar a ordem'});}}
    if(['completed','cancelled'].includes(status)){
      await connection.execute("UPDATE inventory_reservations SET status='cancelled' WHERE work_order_id=? AND org_id=? AND status='active'",[id,req.user.org_id]);
      await connection.execute("UPDATE work_order_material_requests SET approved_quantity=issued_quantity,status=CASE WHEN status='draft' THEN 'rejected' ELSE 'revoked' END WHERE work_order_id=? AND org_id=? AND status IN ('draft','approved')",[id,req.user.org_id]);
    }
    await connection.execute('UPDATE maintenance_work_orders SET status = ?, completed_at = CASE WHEN ? = \'completed\' THEN NOW() ELSE completed_at END WHERE id = ? AND org_id = ?', [status,status,id,req.user.org_id]);
    await connection.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,detail,actor_id) VALUES (?,?,?,?,?)', [req.user.org_id,id,'status_changed',JSON.stringify({from:current,to:status,reason:req.body?.reason||null}),req.user.id]);
    await connection.commit();res.json({id,status});
  } catch (_) { await connection.rollback();res.status(500).json({error:'Erro ao atualizar ordem'}); }finally{connection.release();}
});
router.get('/work-orders/:id/tasks', async (req,res)=>{const id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Ordem inválida'});try{const [rows]=await pool.execute('SELECT * FROM work_order_tasks WHERE work_order_id=? AND org_id=? ORDER BY is_completed,created_at',[id,req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar tarefas'});}});
