router.patch('/work-orders/:id/tasks/:taskId', write, async (req,res)=>{const orderId=Number(req.params.id),taskId=Number(req.params.taskId),completed=req.body?.is_completed;if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(taskId)||taskId<1||typeof completed!=='boolean')return res.status(400).json({error:'Atualização de tarefa inválida'});try{const [result]=await pool.execute('UPDATE work_order_tasks SET is_completed=?,completed_at=CASE WHEN ? THEN NOW() ELSE NULL END,completed_by=CASE WHEN ? THEN ? ELSE NULL END WHERE id=? AND work_order_id=? AND org_id=? AND EXISTS (SELECT 1 FROM maintenance_work_orders wo WHERE wo.id=work_order_tasks.work_order_id AND BINARY wo.org_id=BINARY work_order_tasks.org_id AND wo.status NOT IN (\'completed\',\'cancelled\'))',[completed?1:0,completed,completed,req.user.id,taskId,orderId,req.user.org_id]);if(!result.affectedRows)return res.status(404).json({error:'Tarefa não encontrada'});await pool.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,orderId,'task_status_changed',completed?'completed':'reopened',req.user.id]);res.json({id:taskId,is_completed:completed});}catch(_){res.status(500).json({error:'Erro ao atualizar tarefa'});}});
router.get('/work-orders/:id/audit', async (req,res)=>{const id=Number(req.params.id);if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Ordem inválida'});try{const [rows]=await pool.execute('SELECT action,detail,actor_id,created_at FROM work_order_audit WHERE work_order_id=? AND org_id=? ORDER BY created_at DESC',[id,req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar histórico'});}});
router.post('/work-orders/:id/financial-close', requireRoles('superadmin','admin','manager'), async(req,res)=>{
 const orderId=Number(req.params.id);if(!Number.isSafeInteger(orderId)||orderId<1)return res.status(400).json({error:'Ordem inválida'});
 const c=await pool.getConnection();try{await c.beginTransaction();const [rows]=await c.execute('SELECT status,financial_closed_at FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);if(!rows.length){await c.rollback();return res.status(404).json({error:'Ordem não encontrada'});}if(rows[0].status!=='completed'||rows[0].financial_closed_at){await c.rollback();return res.status(409).json({error:'Ordem deve estar concluída e aberta financeiramente'});}await c.execute('UPDATE maintenance_work_orders SET financial_closed_at=NOW() WHERE id=? AND org_id=?',[orderId,req.user.org_id]);await c.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,actor_id) VALUES (?,?,?,?)',[req.user.org_id,orderId,'financial_closed',req.user.id]);await c.commit();res.json({id:orderId,financial_closed:true});}catch(_){await c.rollback();res.status(500).json({error:'Erro ao fechar financeiro'});}finally{c.release();}
});
router.get('/assets/:id/spares', async (req,res)=>{
  const id=Number(req.params.id); if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Ativo inválido'});
  try { const [rows]=await pool.execute('SELECT s.*, m.code, m.description, m.brand, m.sector, m.location, m.quantity AS stock_quantity, m.min_qty, m.unit_price, m.currency, l.location_code AS functional_location_code, l.name AS functional_location_name FROM asset_spares s JOIN materials m ON m.id=s.material_id AND BINARY m.org_id=BINARY s.org_id LEFT JOIN functional_locations l ON l.id=s.functional_location_id AND BINARY l.org_id=BINARY s.org_id WHERE s.asset_id=? AND s.org_id=? ORDER BY m.code',[id,req.user.org_id]); res.json(rows); } catch(_){res.status(500).json({error:'Erro ao buscar peças'});}
});
router.get('/assets/:id/component-rollup', async (req,res)=>{
  const id=Number(req.params.id);
  if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Ativo inválido'});
  try{
    const [assets]=await pool.execute('SELECT id,parent_asset_id,asset_code,name,description,manufacturer,model,serial_number,status,criticality FROM assets WHERE org_id=?',[req.user.org_id]);
    if(!assets.some(asset=>Number(asset.id)===id))return res.status(404).json({error:'Ativo não encontrado'});
    const byParent=new Map();
    for(const asset of assets){const parent=Number(asset.parent_asset_id);if(!byParent.has(parent))byParent.set(parent,[]);byParent.get(parent).push(asset);}
    const descendants=[],seen=new Set([id]),queue=[id];
    while(queue.length){const parent=queue.shift();for(const child of byParent.get(parent)||[]){const childId=Number(child.id);if(seen.has(childId))continue;seen.add(childId);descendants.push(child);queue.push(childId);}}
    const ids=[id,...descendants.map(asset=>Number(asset.id))];
    const placeholders=ids.map(()=>'?').join(',');
    const [[spares],[positions]]=await Promise.all([
      pool.execute(`SELECT s.asset_id,s.material_id,s.quantity AS bom_quantity,s.minimum_quantity,s.maximum_quantity,m.code,m.description,m.brand,m.sector,m.location,m.quantity AS stock_quantity,m.min_qty,m.unit_price,m.currency FROM asset_spares s JOIN materials m ON m.id=s.material_id AND BINARY m.org_id=BINARY s.org_id WHERE s.org_id=? AND s.asset_id IN (${placeholders})`,[req.user.org_id,...ids]),
      pool.execute(`SELECT p.equipment_id AS asset_id,p.id AS position_id,p.position_number,p.name AS position_name,p.quantity_required,p.expected_item_id AS material_id,m.code,m.description,m.brand,m.sector,m.location,m.quantity AS stock_quantity,m.min_qty,m.unit_price,m.currency FROM component_positions p LEFT JOIN materials m ON m.id=p.expected_item_id AND BINARY m.org_id=BINARY p.org_id WHERE p.org_id=? AND p.equipment_id IN (${placeholders})`,[req.user.org_id,...ids])
    ]);
    const assetById=new Map(assets.map(asset=>[Number(asset.id),asset]));
    const components=new Map(),unlinkedPositions=[];
    for(const position of positions){
      const owner=assetById.get(Number(position.asset_id));
      const quantity=Math.max(0,Number(position.quantity_required)||0);
      if(!position.material_id||!position.code){unlinkedPositions.push({asset_id:position.asset_id,asset_code:owner?.asset_code,asset_name:owner?.name,position_id:position.position_id,position_number:position.position_number,name:position.position_name,quantity});continue;}
      const key=`${position.asset_id}:${position.material_id}`;
      const current=components.get(key)||{...position,asset_code:owner?.asset_code,asset_name:owner?.name,quantity:0,source:'position'};
      current.quantity+=quantity;
      components.set(key,current);
    }
    for(const spare of spares){
      const owner=assetById.get(Number(spare.asset_id));
      const key=`${spare.asset_id}:${spare.material_id}`;
      const quantity=Math.max(0,Number(spare.bom_quantity)||0);
      const current=components.get(key);
      if(current){current.quantity=Math.max(current.quantity,quantity);current.minimum_quantity=spare.minimum_quantity;current.maximum_quantity=spare.maximum_quantity;current.source='position_and_spare';}
      else components.set(key,{...spare,asset_code:owner?.asset_code,asset_name:owner?.name,quantity,source:'spare'});
    }
    const items=[...components.values()].sort((a,b)=>String(a.asset_code).localeCompare(String(b.asset_code))||String(a.code).localeCompare(String(b.code)));
    const totalComponents=descendants.length+items.reduce((sum,item)=>sum+item.quantity,0)+unlinkedPositions.reduce((sum,item)=>sum+item.quantity,0);
    res.json({descendants,components:items,unlinked_positions:unlinkedPositions,total_components:totalComponents});
  }catch(_){res.status(500).json({error:'Erro ao consolidar componentes do equipamento'});}
});
router.get('/assets/:id/spares/:materialId/usage', async (req,res)=>{
  const assetId=Number(req.params.id),materialId=Number(req.params.materialId);
  if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isSafeInteger(materialId)||materialId<1)return res.status(400).json({error:'Ativo ou peça inválidos'});
  try{
    const [linked]=await pool.execute('SELECT s.material_id FROM asset_spares s JOIN assets a ON a.id=s.asset_id AND a.org_id=s.org_id WHERE s.asset_id=? AND s.material_id=? AND s.org_id=?',[assetId,materialId,req.user.org_id]);
    if(!linked.length){const [positions]=await pool.execute('SELECT id FROM component_positions WHERE equipment_id=? AND expected_item_id=? AND org_id=?',[assetId,materialId,req.user.org_id]);if(!positions.length)return res.status(404).json({error:'Peça não vinculada a este equipamento'});}
    const [rows]=await pool.execute("SELECT DATE_FORMAT(mv.created_at,'%Y-%m') AS month,SUM(mv.quantity) AS consumed,COUNT(*) AS movements FROM movements mv JOIN materials m ON m.id=mv.material_id WHERE mv.material_id=? AND m.org_id=? AND mv.type='saida' AND mv.created_at>=DATE_SUB(CURRENT_DATE(),INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(mv.created_at,'%Y-%m') ORDER BY month",[materialId,req.user.org_id]);
    res.json(rows);
  }catch(_){res.status(500).json({error:'Erro ao calcular consumo da peça'});}
});
router.get('/assets/:id/spares/:materialId/reliability', async (req,res)=>{
  const assetId=Number(req.params.id),materialId=Number(req.params.materialId);
  if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isSafeInteger(materialId)||materialId<1)return res.status(400).json({error:'Ativo ou peça inválidos'});
  try{
    const [assets]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);
    const [materials]=await pool.execute('SELECT id FROM materials WHERE id=? AND org_id=?',[materialId,req.user.org_id]);
    if(!assets.length||!materials.length)return res.status(404).json({error:'Ativo ou peça não encontrado'});
    const [linked]=await pool.execute('SELECT s.material_id FROM asset_spares s JOIN assets a ON a.id=s.asset_id AND a.org_id=s.org_id WHERE s.asset_id=? AND s.material_id=? AND s.org_id=?',[assetId,materialId,req.user.org_id]);
    if(!linked.length){const [positions]=await pool.execute('SELECT id FROM component_positions WHERE equipment_id=? AND expected_item_id=? AND org_id=?',[assetId,materialId,req.user.org_id]);if(!positions.length)return res.status(404).json({error:'Peça não vinculada ao equipamento'});}
    const to=new Date(),from=new Date(+to-365*86400000);
    const [rows]=await pool.execute('SELECT d.started_at,d.ended_at,d.work_order_id,d.production_loss_cost,wo.type FROM downtime_records d JOIN maintenance_work_orders wo ON wo.id=d.work_order_id AND BINARY wo.org_id=BINARY d.org_id WHERE d.asset_id=? AND d.causing_material_id=? AND d.org_id=? AND d.started_at<? AND (d.ended_at>? OR d.ended_at IS NULL) ORDER BY d.started_at LIMIT 10001',[assetId,materialId,req.user.org_id,to,from]);
    if(rows.length>10000)return res.status(422).json({error:'Limite de registros para análise excedido.'});
    res.json({period_days:365,...legacyDowntimeReport({from,to,rows})});
  }catch(_){res.status(500).json({error:'Erro ao calcular confiabilidade da peça'});}
});
router.post('/assets/:id/spares/:materialId/requisitions', write, async (req,res)=>{
  const assetId=Number(req.params.id),materialId=Number(req.params.materialId),quantity=req.body?.quantity,reason=req.body?.reason;
  if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000||!text(reason,200))return res.status(400).json({error:'Requisição inválida'});
  const connection=await pool.getConnection();
  try{
    await connection.beginTransaction();
    const [linked]=await connection.execute('SELECT s.material_id FROM asset_spares s JOIN assets a ON a.id=s.asset_id AND a.org_id=s.org_id WHERE s.asset_id=? AND s.material_id=? AND s.org_id=? FOR UPDATE',[assetId,materialId,req.user.org_id]);
    if(!linked.length){const [positions]=await connection.execute('SELECT id FROM component_positions WHERE equipment_id=? AND expected_item_id=? AND org_id=?',[assetId,materialId,req.user.org_id]);if(!positions.length){await connection.rollback();return res.status(404).json({error:'Peça não vinculada ao equipamento'});}}
    const [created]=await connection.execute('INSERT INTO purchase_requisitions (org_id,work_order_id,material_id,requested_quantity,status,reason,created_by) VALUES (?,NULL,?,?,?, ?,?)',[req.user.org_id,materialId,quantity,'requested',reason.trim(),req.user.id]);
    await connection.execute('INSERT INTO purchase_requisition_audit (org_id,requisition_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,created.insertId,'requested',`asset:${assetId}`,req.user.id]);
    await connection.commit();
    res.status(201).json({id:created.insertId,status:'requested'});
  }catch(_){await connection.rollback();res.status(500).json({error:'Erro ao criar requisição'});}finally{connection.release();}
});
router.get('/equipment-models', async (req,res)=>{try{const [rows]=await pool.execute('SELECT id,manufacturer,model_code,name,revision,status FROM equipment_models WHERE org_id=? ORDER BY manufacturer,name',[req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar modelos técnicos'});}});
router.post('/equipment-models', write, async (req,res)=>{const b=req.body||{};if(!text(b.model_code,120)||!text(b.name,200)||(b.manufacturer!==undefined&&!text(b.manufacturer,120)))return res.status(400).json({error:'Modelo inválido'});try{const [r]=await pool.execute('INSERT INTO equipment_models (org_id,manufacturer,model_code,name,description,created_by) VALUES (?,?,?,?,?,?)',[req.user.org_id,b.manufacturer?.trim()||null,b.model_code.trim(),b.name.trim(),b.description?.trim()||null,req.user.id]);res.status(201).json({id:r.insertId});}catch(e){res.status(e.code==='ER_DUP_ENTRY'?409:500).json({error:e.code==='ER_DUP_ENTRY'?'Modelo já existe':'Erro ao criar modelo'});}});
router.post('/assets/:id/modules', write, async (req,res)=>{const id=Number(req.params.id),b=req.body||{};if(!Number.isSafeInteger(id)||id<1||!text(b.code,80)||!text(b.name,200)||!Number.isSafeInteger(b.parent_module_id??0)&&b.parent_module_id!==null)return res.status(400).json({error:'Módulo inválido'});try{const [assets]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[id,req.user.org_id]);if(!assets.length)return res.status(404).json({error:'Ativo não encontrado'});if(b.parent_module_id){const [parents]=await pool.execute('SELECT id FROM equipment_modules WHERE id=? AND equipment_id=? AND org_id=?',[b.parent_module_id,id,req.user.org_id]);if(!parents.length)return res.status(404).json({error:'Módulo pai não encontrado'});}const [r]=await pool.execute('INSERT INTO equipment_modules (org_id,equipment_id,parent_module_id,code,name,module_type,position_order) VALUES (?,?,?,?,?,?,?)',[req.user.org_id,id,b.parent_module_id||null,b.code.trim(),b.name.trim(),b.module_type?.trim()||null,Number.isSafeInteger(b.position_order)?b.position_order:0]);res.status(201).json({id:r.insertId});}catch(e){res.status(e.code==='ER_DUP_ENTRY'?409:500).json({error:e.code==='ER_DUP_ENTRY'?'Código de módulo já existe':'Erro ao criar módulo'});}});
router.post('/assets/:id/component-positions', write, async (req,res)=>{
  const id=Number(req.params.id),b=req.body||{},moduleId=b.module_id==null?null:Number(b.module_id),itemId=b.expected_item_id==null?null:Number(b.expected_item_id);
  const quantity=b.quantity_required;
  if(!Number.isSafeInteger(id)||id<1||!text(b.position_number,80)||!text(b.name,200)||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000||(moduleId!==null&&(!Number.isSafeInteger(moduleId)||moduleId<1))||(itemId!==null&&(!Number.isSafeInteger(itemId)||itemId<1)))return res.status(400).json({error:'Posição de componente inválida'});
  const connection=await pool.getConnection();
  try{
    await connection.beginTransaction();
    const [assets]=await connection.execute('SELECT id,functional_location_id FROM assets WHERE id=? AND org_id=? FOR UPDATE',[id,req.user.org_id]);
    if(!assets.length){await connection.rollback();return res.status(404).json({error:'Ativo não encontrado'});}
    if(moduleId!==null){const [modules]=await connection.execute('SELECT id FROM equipment_modules WHERE id=? AND equipment_id=? AND org_id=?',[moduleId,id,req.user.org_id]);if(!modules.length){await connection.rollback();return res.status(404).json({error:'Módulo não encontrado'});}}
    if(itemId!==null){const [items]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=? AND is_active=1',[itemId,req.user.org_id]);if(!items.length){await connection.rollback();return res.status(404).json({error:'Peça não encontrada'});}}
    const [created]=await connection.execute('INSERT INTO component_positions (org_id,equipment_id,module_id,position_number,name,component_type,expected_item_id,quantity_required,is_critical,is_spare_relevant) VALUES (?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,id,moduleId,b.position_number.trim(),b.name.trim(),text(b.component_type,80)?b.component_type.trim():null,itemId,quantity,b.is_critical?1:0,b.is_spare_relevant===false?0:1]);
    if(itemId!==null&&b.is_spare_relevant!==false){
      const [spares]=await connection.execute('SELECT id,quantity FROM asset_spares WHERE asset_id=? AND material_id=? AND org_id=? FOR UPDATE',[id,itemId,req.user.org_id]);
      if(!spares.length){
        await connection.execute('INSERT INTO asset_spares (org_id,asset_id,material_id,quantity,functional_location_id) VALUES (?,?,?,?,?)',[req.user.org_id,id,itemId,quantity,assets[0].functional_location_id??null]);
        await connection.execute('INSERT INTO asset_spare_audit (org_id,asset_id,material_id,action,detail,actor_id) VALUES (?,?,?,?,?,?)',[req.user.org_id,id,itemId,'auto_add',`position_id=${created.insertId};quantity=${quantity}`,req.user.id]);
      }else{
        await connection.execute('INSERT INTO asset_spare_audit (org_id,asset_id,material_id,action,detail,actor_id) VALUES (?,?,?,?,?,?)',[req.user.org_id,id,itemId,'position_linked',`position_id=${created.insertId};existing_quantity=${spares[0].quantity}`,req.user.id]);
      }
    }
    await connection.commit();res.status(201).json({id:created.insertId,spare_auto_added:itemId!==null&&b.is_spare_relevant!==false});
  }catch(error){await connection.rollback();res.status(error.code==='ER_DUP_ENTRY'?409:500).json({error:error.code==='ER_DUP_ENTRY'?'Posição já existe':'Erro ao criar posição'});}finally{connection.release();}
});
router.post('/component-positions/:id/instances', write, async (req,res)=>{const positionId=Number(req.params.id),b=req.body||{},serial=text(b.serial_number,120)?b.serial_number.trim():null,installedAt=b.installed_at||null,itemId=Number.isSafeInteger(b.inventory_item_id)?b.inventory_item_id:null,workOrderId=Number.isSafeInteger(b.work_order_id)?b.work_order_id:null;if(!Number.isSafeInteger(positionId)||positionId<1||(b.serial_number!==undefined&&!serial)||(installedAt!==null&&(typeof installedAt!=='string'||Number.isNaN(Date.parse(installedAt))))||(b.manufacturer_part_number!==undefined&&!text(b.manufacturer_part_number,120)))return res.status(400).json({error:'Instância de componente inválida'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [positions]=await connection.execute('SELECT id FROM component_positions WHERE id=? AND org_id=? FOR UPDATE',[positionId,req.user.org_id]);if(!positions.length){await connection.rollback();return res.status(404).json({error:'Posição de componente não encontrada'});}if(itemId!==null){const [items]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=?',[itemId,req.user.org_id]);if(!items.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}}if(workOrderId!==null){const [orders]=await connection.execute('SELECT id FROM maintenance_work_orders WHERE id=? AND org_id=?',[workOrderId,req.user.org_id]);if(!orders.length){await connection.rollback();return res.status(404).json({error:'Ordem não encontrada'});}}if(serial){const [duplicates]=await connection.execute('SELECT id FROM component_instances WHERE org_id=? AND serial_number=? FOR UPDATE',[req.user.org_id,serial]);if(duplicates.length){await connection.rollback();return res.status(409).json({error:'Número de série já cadastrado'});}}const [created]=await connection.execute('INSERT INTO component_instances (org_id,component_position_id,inventory_item_id,serial_number,batch_number,manufacturer,manufacturer_part_number,installed_at,status,operating_hours_at_install,operating_cycles_at_install,warranty_start,warranty_end) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,positionId,itemId,serial,text(b.batch_number,120)?b.batch_number.trim():null,text(b.manufacturer,120)?b.manufacturer.trim():null,b.manufacturer_part_number?.trim()||null,installedAt,'installed',typeof b.operating_hours_at_install==='number'&&Number.isFinite(b.operating_hours_at_install)?b.operating_hours_at_install:null,typeof b.operating_cycles_at_install==='number'&&Number.isFinite(b.operating_cycles_at_install)?b.operating_cycles_at_install:null,b.warranty_start||null,b.warranty_end||null]);await connection.execute('UPDATE component_positions SET installed_instance_id=? WHERE id=? AND org_id=?',[created.insertId,positionId,req.user.org_id]);await connection.execute('INSERT INTO component_installation_history (org_id,component_position_id,new_instance_id,installed_at,work_order_id,technician_id,reason,notes) VALUES (?,?,?,?,?,?,?,?)',[req.user.org_id,positionId,created.insertId,installedAt,workOrderId,req.user.id,text(b.reason,300)?b.reason.trim():'initial_install',text(b.notes,5000)?b.notes.trim():null]);await connection.commit();res.status(201).json({id:created.insertId,component_position_id:positionId,status:'installed'});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao registrar instância'});}finally{connection.release();}});
router.post('/component-positions/:id/replace', write, async (req,res)=>{const positionId=Number(req.params.id),oldId=Number(req.body?.old_instance_id),b=req.body||{},serial=text(b.serial_number,120)?b.serial_number.trim():null,installedAt=b.installed_at||null,itemId=Number.isSafeInteger(b.inventory_item_id)?b.inventory_item_id:null,workOrderId=Number.isSafeInteger(b.work_order_id)?b.work_order_id:null;if(!Number.isSafeInteger(positionId)||positionId<1||!Number.isSafeInteger(oldId)||oldId<1||(b.serial_number!==undefined&&!serial)||(installedAt!==null&&(typeof installedAt!=='string'||Number.isNaN(Date.parse(installedAt))))||(b.reason!==undefined&&!text(b.reason,300)))return res.status(400).json({error:'Substituição inválida'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [positions]=await connection.execute('SELECT id FROM component_positions WHERE id=? AND org_id=? FOR UPDATE',[positionId,req.user.org_id]);const [oldRows]=await connection.execute("SELECT id FROM component_instances WHERE id=? AND component_position_id=? AND org_id=? AND status='installed' FOR UPDATE",[oldId,positionId,req.user.org_id]);if(!positions.length||!oldRows.length){await connection.rollback();return res.status(409).json({error:'Componente instalado não encontrado'});}if(itemId!==null){const [items]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=?',[itemId,req.user.org_id]);if(!items.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}}if(workOrderId!==null){const [orders]=await connection.execute('SELECT id FROM maintenance_work_orders WHERE id=? AND org_id=?',[workOrderId,req.user.org_id]);if(!orders.length){await connection.rollback();return res.status(404).json({error:'Ordem não encontrada'});}}if(serial){const [duplicates]=await connection.execute('SELECT id FROM component_instances WHERE org_id=? AND serial_number=? FOR UPDATE',[req.user.org_id,serial]);if(duplicates.length){await connection.rollback();return res.status(409).json({error:'Número de série já cadastrado'});}}await connection.execute("UPDATE component_instances SET status='removed',removed_at=? WHERE id=? AND org_id=?",[installedAt,oldId,req.user.org_id]);const [created]=await connection.execute('INSERT INTO component_instances (org_id,component_position_id,inventory_item_id,serial_number,batch_number,manufacturer,manufacturer_part_number,installed_at,status,source_work_order_id) VALUES (?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,positionId,itemId,serial,text(b.batch_number,120)?b.batch_number.trim():null,text(b.manufacturer,120)?b.manufacturer.trim():null,text(b.manufacturer_part_number,120)?b.manufacturer_part_number.trim():null,installedAt,'installed',workOrderId]);await connection.execute('UPDATE component_positions SET installed_instance_id=? WHERE id=? AND org_id=?',[created.insertId,positionId,req.user.org_id]);await connection.execute('INSERT INTO component_installation_history (org_id,component_position_id,old_instance_id,new_instance_id,installed_at,removed_at,work_order_id,technician_id,reason,notes) VALUES (?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,positionId,oldId,created.insertId,installedAt,workOrderId,req.user.id,b.reason.trim(),text(b.notes,5000)?b.notes.trim():null]);await connection.commit();res.status(201).json({old_instance_id:oldId,new_instance_id:created.insertId,component_position_id:positionId});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao substituir componente'});}finally{connection.release();}});
router.post('/assets/:id/revisions', write, async (req,res)=>{const assetId=Number(req.params.id),b=req.body||{};if(!Number.isSafeInteger(assetId)||assetId<1||!text(b.revision_code,40)||(b.effective_from!==undefined&&!/^\d{4}-\d{2}-\d{2}$/.test(b.effective_from))||(b.effective_to!==undefined&&!/^\d{4}-\d{2}-\d{2}$/.test(b.effective_to)))return res.status(400).json({error:'Revisão inválida'});try{const [assets]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);if(!assets.length)return res.status(404).json({error:'Ativo não encontrado'});const [created]=await pool.execute('INSERT INTO equipment_revisions (org_id,equipment_id,revision_code,effective_from,effective_to,change_order,notes) VALUES (?,?,?,?,?,?,?)',[req.user.org_id,assetId,b.revision_code.trim(),b.effective_from||null,b.effective_to||null,text(b.change_order,120)?b.change_order.trim():null,text(b.notes,5000)?b.notes.trim():null]);res.status(201).json({id:created.insertId,asset_id:assetId,status:'draft'});}catch(e){res.status(e.code==='ER_DUP_ENTRY'?409:500).json({error:e.code==='ER_DUP_ENTRY'?'Revisão já existe':'Erro ao criar revisão'});}});
router.patch('/assets/:assetId/revisions/:id/status', requireRoles('superadmin','admin','manager'), async (req,res)=>{const assetId=Number(req.params.assetId),id=Number(req.params.id),status=req.body?.status;if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isSafeInteger(id)||id<1||!['under_review','approved','active','superseded','obsolete'].includes(status))return res.status(400).json({error:'Status de revisão inválido'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [revisions]=await connection.execute('SELECT status FROM equipment_revisions WHERE id=? AND equipment_id=? AND org_id=? FOR UPDATE',[id,assetId,req.user.org_id]);if(!revisions.length){await connection.rollback();return res.status(404).json({error:'Revisão não encontrada'});}const allowed={draft:['under_review'],under_review:['approved'],approved:['active'],active:['superseded','obsolete'],superseded:[],obsolete:[]};if(!allowed[revisions[0].status]?.includes(status)){await connection.rollback();return res.status(409).json({error:'Transição de revisão inválida'});}if(status==='active')await connection.execute("UPDATE equipment_revisions SET status='superseded' WHERE equipment_id=? AND org_id=? AND status='active'",[assetId,req.user.org_id]);await connection.execute('UPDATE equipment_revisions SET status=?,approved_by=CASE WHEN ? IN (\'approved\',\'active\') THEN ? ELSE approved_by END WHERE id=? AND equipment_id=? AND org_id=?',[status,status,req.user.id,id,assetId,req.user.org_id]);await connection.commit();res.json({id,status});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao atualizar revisão'});}finally{connection.release();}});
router.post('/assets/:id/visuals', write, async (req,res)=>{const assetId=Number(req.params.id),b=req.body||{},moduleId=b.module_id==null?null:Number(b.module_id),types=['photo','normal_view','exploded_view','technical_illustration','cutaway','section_view','3d_model','ar_reference'],orientations=['front','rear','left','right','top','bottom','isometric','custom'];if(!Number.isSafeInteger(assetId)||assetId<1||!types.includes(b.type)||!orientations.includes(b.orientation||'custom')||!text(b.title,200)||(moduleId!==null&&(!Number.isSafeInteger(moduleId)||moduleId<1)))return res.status(400).json({error:'Visual inválido'});let file;try{file=validateAttachment(b);}catch(_){return res.status(400).json({error:'Arquivo visual inválido'});}try{const [assets]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);if(!assets.length)return res.status(404).json({error:'Ativo não encontrado'});if(moduleId!==null){const [modules]=await pool.execute('SELECT id FROM equipment_modules WHERE id=? AND equipment_id=? AND org_id=?',[moduleId,assetId,req.user.org_id]);if(!modules.length)return res.status(404).json({error:'Módulo não encontrado'});}const [created]=await pool.execute('INSERT INTO equipment_visuals (org_id,equipment_id,module_id,type,orientation,title,description,revision,status,filename,mime_type,file_data,file_url,file_size_kb,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,assetId,moduleId,b.type,b.orientation||'custom',b.title.trim(),text(b.description,5000)?b.description.trim():null,text(b.revision,40)?b.revision.trim():null,'draft',file.filename,file.mime_type,file.file_data,file.file_url,file.size,req.user.id]);res.status(201).json({id:created.insertId,type:b.type,title:b.title.trim(),filename:file.filename,module_id:moduleId});}catch(_){res.status(500).json({error:'Erro ao registrar visual'});}});
