router.post('/assets/:id/documents', write, async (req,res)=>{const assetId=Number(req.params.id),b=req.body||{},moduleId=b.module_id==null?null:Number(b.module_id),types=['manual','datasheet','electrical','mechanical','hydraulic','pneumatic','pid','layout','certificate','inspection','other'];if(!Number.isSafeInteger(assetId)||assetId<1||!text(b.document_number,120)||!text(b.title,200)||!text(b.revision_code,40)||!types.includes(b.document_type||'other')||(moduleId!==null&&(!Number.isSafeInteger(moduleId)||moduleId<1)))return res.status(400).json({error:'Documento inválido'});let file;try{file=validateAttachment(b);}catch(_){return res.status(400).json({error:'Arquivo técnico inválido'});}const connection=await pool.getConnection();try{await connection.beginTransaction();const [assets]=await connection.execute('SELECT id FROM assets WHERE id=? AND org_id=? FOR UPDATE',[assetId,req.user.org_id]);if(!assets.length){await connection.rollback();return res.status(404).json({error:'Ativo não encontrado'});}if(moduleId!==null){const [modules]=await connection.execute('SELECT id FROM equipment_modules WHERE id=? AND equipment_id=? AND org_id=?',[moduleId,assetId,req.user.org_id]);if(!modules.length){await connection.rollback();return res.status(404).json({error:'Módulo não encontrado'});}}const [doc]=await connection.execute('INSERT INTO technical_documents (org_id,equipment_id,owner_type,owner_id,document_number,title,document_type,description,created_by) VALUES (?,?,?,?,?,?,?,?,?)',[req.user.org_id,assetId,moduleId!==null?'module':'equipment',moduleId||assetId,b.document_number.trim(),b.title.trim(),b.document_type||'other',text(b.description,5000)?b.description.trim():null,req.user.id]);const [revision]=await connection.execute('INSERT INTO technical_document_revisions (org_id,document_id,revision_code,filename,mime_type,file_data,file_url,file_size_kb,change_description,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,doc.insertId,b.revision_code.trim(),file.filename,file.mime_type,file.file_data,file.file_url,file.size,text(b.change_description,5000)?b.change_description.trim():null,req.user.id]);await connection.execute('UPDATE technical_documents SET current_revision_id=? WHERE id=? AND org_id=?',[revision.insertId,doc.insertId,req.user.org_id]);await connection.commit();res.status(201).json({id:doc.insertId,revision_id:revision.insertId});}catch(e){await connection.rollback();res.status(e.code==='ER_DUP_ENTRY'?409:500).json({error:e.code==='ER_DUP_ENTRY'?'Documento ou revisão já existe':'Erro ao registrar documento'});}finally{connection.release();}});
