router.patch('/documents/:documentId/revisions/:id/status', requireRoles('superadmin','admin','manager'), async (req,res)=>{const documentId=Number(req.params.documentId),id=Number(req.params.id),status=req.body?.status,allowed={draft:['under_review'],under_review:['approved'],approved:['active'],active:['superseded','obsolete'],superseded:[],obsolete:[]};if(!Number.isSafeInteger(documentId)||documentId<1||!Number.isSafeInteger(id)||id<1||!Object.values(allowed).flat().includes(status))return res.status(400).json({error:'Status de revisão inválido'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [rows]=await connection.execute('SELECT r.status,d.id AS document_id FROM technical_document_revisions r JOIN technical_documents d ON d.id=r.document_id AND d.org_id=r.org_id WHERE r.id=? AND r.document_id=? AND r.org_id=? FOR UPDATE',[id,documentId,req.user.org_id]);if(!rows.length){await connection.rollback();return res.status(404).json({error:'Revisão não encontrada'});}if(!allowed[rows[0].status]?.includes(status)){await connection.rollback();return res.status(409).json({error:'Transição de revisão inválida'});}if(status==='active')await connection.execute("UPDATE technical_document_revisions SET status='superseded' WHERE document_id=? AND org_id=? AND status='active'",[documentId,req.user.org_id]);await connection.execute("UPDATE technical_document_revisions SET status=?,approved_by=CASE WHEN ? IN ('approved','active') THEN ? ELSE approved_by END WHERE id=? AND document_id=? AND org_id=?",[status,status,req.user.id,id,documentId,req.user.org_id]);await connection.execute('UPDATE technical_documents SET status=?,current_revision_id=CASE WHEN ?=\'active\' THEN ? ELSE current_revision_id END WHERE id=? AND org_id=?',[status,status,id,documentId,req.user.org_id]);await connection.commit();res.json({id,status});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao atualizar revisão'});}finally{connection.release();}});
