router.patch('/purchase-requisitions/:id/status', requireRoles('superadmin','admin','manager'), async (req,res)=>{const id=Number(req.params.id),status=req.body?.status,reason=req.body?.reason;if(!Number.isSafeInteger(id)||id<1||!['requested','approved','cancelled'].includes(status)||(reason!==undefined&&(!text(reason,300))))return res.status(400).json({error:'Atualização de requisição inválida'});try{const [rows]=await pool.execute('SELECT status FROM purchase_requisitions WHERE id=? AND org_id=?',[id,req.user.org_id]);if(!rows.length)return res.status(404).json({error:'Requisição não encontrada'});const transitions={draft:['requested','approved','cancelled'],requested:['approved','cancelled'],approved:[],cancelled:[],fulfilled:[]};if(!transitions[rows[0].status]?.includes(status))return res.status(409).json({error:'Transição de requisição inválida'});await pool.execute("UPDATE purchase_requisitions SET status=?,approved_by=CASE WHEN ?='approved' THEN ? ELSE approved_by END,approved_at=CASE WHEN ?='approved' THEN NOW() ELSE approved_at END,cancel_reason=CASE WHEN ?='cancelled' THEN ? ELSE cancel_reason END WHERE id=? AND org_id=?",[status,status,req.user.id,status,status,reason?.trim()||null,id,req.user.org_id]);await pool.execute('INSERT INTO purchase_requisition_audit (org_id,requisition_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,id,'status_changed',`${rows[0].status}->${status}`,req.user.id]);res.json({id,status});}catch(_){res.status(500).json({error:'Erro ao atualizar requisição'});}});
router.post('/purchase-requisitions/:id/purchase-orders', requireRoles('superadmin','admin','manager'), async (req,res)=>{const id=Number(req.params.id),supplierId=Number(req.body?.supplier_id),unitPrice=req.body?.unit_price,expectedAt=req.body?.expected_at;if(!Number.isSafeInteger(id)||id<1||!Number.isSafeInteger(supplierId)||supplierId<1||typeof unitPrice!=='number'||!Number.isFinite(unitPrice)||unitPrice<0||(expectedAt!==undefined&&expectedAt!==null&&(typeof expectedAt!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(expectedAt))))return res.status(400).json({error:'Pedido de compra inválido'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [requisitions]=await connection.execute("SELECT material_id,requested_quantity,status FROM purchase_requisitions WHERE id=? AND org_id=? FOR UPDATE",[id,req.user.org_id]);if(!requisitions.length){await connection.rollback();return res.status(404).json({error:'Requisição não encontrada'});}if(requisitions[0].status!=='approved'){await connection.rollback();return res.status(409).json({error:'Requisição deve estar aprovada'});}const [suppliers]=await connection.execute('SELECT id FROM suppliers WHERE id=? AND (org_id=? OR org_id IS NULL) AND is_active=1',[supplierId,req.user.org_id]);if(!suppliers.length){await connection.rollback();return res.status(404).json({error:'Fornecedor não encontrado'});}const snapshot=await purchaseSnapshot(connection,req.user.org_id,requisitions[0].material_id,Number(requisitions[0].requested_quantity),unitPrice,req.body?.purchase_unit);const [created]=await connection.execute('INSERT INTO maintenance_purchase_orders (org_id,requisition_id,supplier_id,material_id,quantity,unit_price,expected_at,created_by,purchase_unit,purchase_factor,purchase_quantity,purchase_unit_price) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,id,supplierId,requisitions[0].material_id,snapshot.baseQuantity,snapshot.basePrice,expectedAt||null,req.user.id,snapshot.unit,snapshot.factor,snapshot.purchaseQuantity,snapshot.purchasePrice]);const poNumber=`MPO-${String(created.insertId).padStart(8,'0')}`;await connection.execute('UPDATE maintenance_purchase_orders SET po_number=? WHERE id=? AND org_id=?',[poNumber,created.insertId,req.user.org_id]);await connection.execute("UPDATE purchase_requisitions SET status='fulfilled' WHERE id=? AND org_id=?",[id,req.user.org_id]);await connection.execute('INSERT INTO purchase_requisition_audit (org_id,requisition_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,id,'purchase_order_created',poNumber,req.user.id]);await connection.commit();res.status(201).json({id:created.insertId,po_number:poNumber,requisition_id:id});}catch(_){await connection.rollback();res.status(_.status||500).json({error:_.status?_.message:'Erro ao criar pedido de compra'});}finally{connection.release();}});
router.get('/purchase-orders', async (req,res)=>{try{const [rows]=await pool.execute('SELECT p.*,m.code,m.description,s.name AS supplier_name FROM maintenance_purchase_orders p JOIN materials m ON m.id=p.material_id AND m.org_id=p.org_id JOIN suppliers s ON s.id=p.supplier_id WHERE p.org_id=? ORDER BY p.created_at DESC',[req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar pedidos de compra'});}});
router.post('/purchase-orders/:id/receive', requireRoles('superadmin','admin','manager'), async (req,res)=>{const id=Number(req.params.id);let quantity=req.body?.quantity;if(!Number.isSafeInteger(id)||id<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>1000000||(req.body?.unit!==undefined&&!['base','purchase'].includes(req.body.unit)))return res.status(400).json({error:'Recebimento inválido'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [orders]=await connection.execute('SELECT id,material_id,quantity,received_quantity,status,po_number,purchase_factor FROM maintenance_purchase_orders WHERE id=? AND org_id=? FOR UPDATE',[id,req.user.org_id]);if(!orders.length){await connection.rollback();return res.status(404).json({error:'Pedido não encontrado'});}const order=orders[0];if(req.body?.unit==='purchase')quantity=Number((quantity*Number(order.purchase_factor||1)).toFixed(3));if(!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>1000000){await connection.rollback();return res.status(400).json({error:'Quantidade convertida inválida'});}if(['received','cancelled'].includes(order.status)||Number((Number(order.quantity)-Number(order.received_quantity)).toFixed(3))<quantity){await connection.rollback();return res.status(409).json({error:'Quantidade não disponível para recebimento'});}const [materials]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=? FOR UPDATE',[order.material_id,req.user.org_id]);if(!materials.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}const received=Number(order.received_quantity)+quantity,status=received>=Number(order.quantity)?'received':'partial';await connection.execute('UPDATE maintenance_purchase_orders SET received_quantity=?,status=?,received_at=CASE WHEN ?=\'received\' THEN NOW() ELSE received_at END WHERE id=? AND org_id=?',[received,status,status,id,req.user.org_id]);await connection.execute('UPDATE materials SET quantity=quantity+? WHERE id=? AND org_id=?',[quantity,order.material_id,req.user.org_id]);await connection.execute("INSERT INTO movements (material_id,type,quantity,responsible,reason,notes) VALUES (?, 'entrada', ?, ?, 'maintenance_purchase_receipt', ?)",[order.material_id,quantity,req.user.email,`purchase_order:${order.po_number}`]);await connection.commit();res.status(201).json({id,received_quantity:received,status});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao receber pedido'});}finally{connection.release();}});
router.post('/assets/:id/spares', write, async (req,res)=>{
  const assetId=Number(req.params.id), b=req.body||{}, materialId=Number(b.material_id), quantity=b.quantity;
  const minimum=b.minimum_quantity==null?null:b.minimum_quantity, maximum=b.maximum_quantity==null?null:b.maximum_quantity;
  const locationId=b.functional_location_id==null?null:Number(b.functional_location_id);
  const validAmount=value=>value===null||(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100000);
  if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000||!validAmount(minimum)||!validAmount(maximum)||(minimum!==null&&maximum!==null&&minimum>maximum)||(maximum!==null&&quantity>maximum)||(locationId!==null&&(!Number.isSafeInteger(locationId)||locationId<1)))return res.status(400).json({error:'Peça, limites ou localização inválidos'});
  const connection=await pool.getConnection();
  try { await connection.beginTransaction();
    const [assets]=await connection.execute('SELECT id,functional_location_id FROM assets WHERE id=? AND org_id=? FOR UPDATE',[assetId,req.user.org_id]);
    const [materials]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=? AND is_active=1',[materialId,req.user.org_id]);
    if(!assets.length||!materials.length){await connection.rollback();return res.status(404).json({error:'Ativo ou material não encontrado'});}
    const effectiveLocation=locationId??assets[0].functional_location_id??null;
    if(effectiveLocation!==null){const [locations]=await connection.execute('SELECT id FROM functional_locations WHERE id=? AND org_id=?',[effectiveLocation,req.user.org_id]);if(!locations.length){await connection.rollback();return res.status(404).json({error:'Localização funcional não encontrada'});}}
    await connection.execute('INSERT INTO asset_spares (org_id,asset_id,material_id,quantity,minimum_quantity,maximum_quantity,functional_location_id) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity),minimum_quantity=VALUES(minimum_quantity),maximum_quantity=VALUES(maximum_quantity),functional_location_id=VALUES(functional_location_id)',[req.user.org_id,assetId,materialId,quantity,minimum,maximum,effectiveLocation]);
    await connection.execute('INSERT INTO asset_spare_audit (org_id,asset_id,material_id,action,detail,actor_id) VALUES (?,?,?,?,?,?)',[req.user.org_id,assetId,materialId,'manual_upsert',`quantity=${quantity};min=${minimum??''};max=${maximum??''};location=${effectiveLocation??''}`,req.user.id]);
    await connection.commit();res.status(201).json({asset_id:assetId,material_id:materialId,quantity,minimum_quantity:minimum,maximum_quantity:maximum,functional_location_id:effectiveLocation});
  }catch(_){await connection.rollback();res.status(500).json({error:'Erro ao vincular peça'});}finally{connection.release();}
});
