router.post('/work-orders/:id/material-requests', write, async(req,res)=>{
  const orderId=Number(req.params.id),materialId=req.body?.material_id,quantity=req.body?.quantity;
  if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000)return res.status(400).json({error:'Solicitação de peça inválida'});
  const connection=await pool.getConnection();try{await connection.beginTransaction();const [orders]=await connection.execute('SELECT status FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);const [materials]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=? AND is_active=1',[materialId,req.user.org_id]);if(!orders.length||!materials.length){await connection.rollback();return res.status(404).json({error:'Ordem ou material não encontrado'});}if(['completed','cancelled'].includes(orders[0].status)){await connection.rollback();return res.status(409).json({error:'Ordem encerrada'});}const [existing]=await connection.execute('SELECT id,status FROM work_order_material_requests WHERE work_order_id=? AND material_id=? AND org_id=? FOR UPDATE',[orderId,materialId,req.user.org_id]);if(existing.length&&existing[0].status==='approved'){await connection.rollback();return res.status(409).json({error:'Solicitação já aprovada; use o saldo autorizado'});}await connection.execute("INSERT INTO work_order_material_requests (org_id,work_order_id,material_id,requested_quantity,requested_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE requested_quantity=issued_quantity+VALUES(requested_quantity),approved_quantity=NULL,status='draft',requested_by=VALUES(requested_by),approved_by=NULL,approved_at=NULL",[req.user.org_id,orderId,materialId,quantity,req.user.id]);await connection.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,orderId,'material_requested',`${materialId}:${quantity}`,req.user.id]);await connection.commit();res.status(201).json({work_order_id:orderId,material_id:materialId,requested_quantity:quantity,status:'draft'});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao solicitar peça'});}finally{connection.release();}
});
router.patch('/work-orders/:id/material-requests/:materialId', requireRoles('superadmin','admin','manager'), async(req,res)=>{
  const orderId=Number(req.params.id),materialId=Number(req.params.materialId),status=req.body?.status;
  if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1||!['approved','rejected','revoked'].includes(status)||(status==='revoked'&&!text(req.body?.reason,300)))return res.status(400).json({error:'Decisão inválida; informe o motivo da revogação'});
  const connection=await pool.getConnection();
  try {
    await connection.beginTransaction();
    const [orders]=await connection.execute('SELECT status FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);
    if(!orders.length||['completed','cancelled'].includes(orders[0].status)){await connection.rollback();return res.status(409).json({error:'Ordem não disponível para decisão'});}
    const [requests]=await connection.execute('SELECT id,status,requested_quantity,issued_quantity FROM work_order_material_requests WHERE work_order_id=? AND material_id=? AND org_id=? FOR UPDATE',[orderId,materialId,req.user.org_id]);
    if(!requests.length){await connection.rollback();return res.status(409).json({error:'Solicitação não encontrada'});}
    const decision=decideAuthorization(requests[0],status,req.body?.approved_quantity);
    if(status==='revoked')await connection.execute("UPDATE inventory_reservations SET status='cancelled' WHERE work_order_id=? AND material_id=? AND org_id=? AND status='active'",[orderId,materialId,req.user.org_id]);
    await connection.execute('UPDATE work_order_material_requests SET status=?,approved_quantity=?,approved_by=?,approved_at=NOW() WHERE id=? AND org_id=?',[decision.status,decision.approved,req.user.id,requests[0].id,req.user.org_id]);
    await connection.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,orderId,'material_'+status,JSON.stringify({material_id:materialId,approved_quantity:decision.approved,reason:req.body?.reason||null}),req.user.id]);
    await connection.commit();res.json({work_order_id:orderId,material_id:materialId,status,approved_quantity:decision.approved});
  }catch(error){await connection.rollback();res.status(error.status||500).json({error:error.status?error.message:'Erro ao decidir solicitação'});}finally{connection.release();}
});
router.post('/work-orders/:id/materials', write, async (req,res)=>{
  const orderId=Number(req.params.id), materialId=req.body?.material_id, quantity=req.body?.quantity;
  if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000) return res.status(400).json({error:'Material ou quantidade inválida'});
  const connection=await pool.getConnection();
  try { await connection.beginTransaction();
    const [wo]=await connection.execute('SELECT id,asset_id,status FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);
    if(!wo.length){await connection.rollback();return res.status(404).json({error:'Ordem não encontrada'});} if(wo[0].status!=='in_progress'){await connection.rollback();return res.status(409).json({error:'Inicie a ordem liberada antes de consumir peças'});}
    const [requests]=await connection.execute("SELECT id,COALESCE(approved_quantity,requested_quantity) AS requested_quantity,issued_quantity FROM work_order_material_requests WHERE work_order_id=? AND material_id=? AND org_id=? AND status='approved' FOR UPDATE",[orderId,materialId,req.user.org_id]);
    if(!requests.length||Number((Number(requests[0].requested_quantity)-Number(requests[0].issued_quantity)).toFixed(3))<quantity){await connection.rollback();return res.status(409).json({error:'Solicite e obtenha aprovação para a quantidade antes da baixa'});}
    const [mat]=await connection.execute('SELECT id,quantity,unit_price FROM materials WHERE id=? AND org_id=? AND is_active=1 FOR UPDATE',[materialId,req.user.org_id]);
    if(!mat.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}
    const [otherReservations]=await connection.execute("SELECT COALESCE(SUM(quantity),0) AS quantity FROM inventory_reservations WHERE org_id=? AND material_id=? AND work_order_id<>? AND status='active'",[req.user.org_id,materialId,orderId]);
    const available=Number((Number(mat[0].quantity)-Number(otherReservations[0].quantity)).toFixed(3));
    if(available<quantity){await connection.execute("INSERT INTO purchase_requisitions (org_id,work_order_id,material_id,requested_quantity,reason,created_by) VALUES (?,?,?,?, 'maintenance_shortage', ?) ON DUPLICATE KEY UPDATE requested_quantity=GREATEST(requested_quantity,VALUES(requested_quantity)),status='draft'",[req.user.org_id,orderId,materialId,quantity-Math.max(0,available),req.user.id]);await connection.commit();return res.status(409).json({error:'Saldo disponível insuficiente; requisição criada'});}
    await connection.execute('UPDATE materials SET quantity=quantity-? WHERE id=? AND org_id=? AND quantity>=?',[quantity,materialId,req.user.org_id,quantity]);
    await connection.execute("UPDATE inventory_reservations SET status=CASE WHEN quantity-? <= 0 THEN 'issued' ELSE status END,quantity=GREATEST(quantity-?,0) WHERE work_order_id=? AND material_id=? AND org_id=? AND status='active'",[quantity,quantity,orderId,materialId,req.user.org_id]);
    await connection.execute('INSERT INTO work_order_materials (org_id,work_order_id,material_id,quantity,unit_cost,material_cost,issued_at,issued_by) VALUES (?,?,?,?,?,?,NOW(),?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity), material_cost=material_cost+VALUES(material_cost), issued_at=NOW(), issued_by=VALUES(issued_by)',[req.user.org_id,orderId,materialId,quantity,mat[0].unit_price,Number(mat[0].unit_price)*quantity,req.user.id]);
    await connection.execute("UPDATE work_order_material_requests SET status=CASE WHEN issued_quantity+?>=COALESCE(approved_quantity,requested_quantity) THEN 'fulfilled' ELSE status END,issued_quantity=issued_quantity+? WHERE id=? AND org_id=?",[quantity,quantity,requests[0].id,req.user.org_id]);
    await connection.execute("INSERT INTO movements (material_id,type,quantity,responsible,reason,notes) VALUES (?, 'saida', ?, ?, 'maintenance_consumption', ?)",[materialId,quantity,req.user.email,`work_order:${orderId}`]);
    await connection.commit(); res.status(201).json({work_order_id:orderId,material_id:materialId,quantity,new_stock:mat[0].quantity-quantity});
  } catch(_){await connection.rollback();res.status(500).json({error:'Erro ao consumir material'});} finally {connection.release();}
});
router.post('/work-orders/:id/materials/:materialId/return', write, async (req,res)=>{const orderId=Number(req.params.id),materialId=Number(req.params.materialId),quantity=req.body?.quantity;if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001)return res.status(400).json({error:'Devolução inválida'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [closing]=await connection.execute('SELECT financial_closed_at FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);if(!closing.length||closing[0].financial_closed_at){await connection.rollback();return res.status(409).json({error:'Ordem não disponível ou fechada financeiramente'});}const [line]=await connection.execute('SELECT quantity,returned_quantity FROM work_order_materials WHERE work_order_id=? AND material_id=? AND org_id=? FOR UPDATE',[orderId,materialId,req.user.org_id]);if(!line.length||Number((Number(line[0].quantity)-Number(line[0].returned_quantity)).toFixed(3))<quantity){await connection.rollback();return res.status(409).json({error:'Quantidade não disponível para devolução'});}const [material]=await connection.execute('SELECT id FROM materials WHERE id=? AND org_id=? FOR UPDATE',[materialId,req.user.org_id]);if(!material.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}await connection.execute('UPDATE work_order_materials SET returned_quantity=returned_quantity+?,material_cost=GREATEST(material_cost-unit_cost*?,0) WHERE work_order_id=? AND material_id=? AND org_id=?',[quantity,quantity,orderId,materialId,req.user.org_id]);await connection.execute('UPDATE materials SET quantity=quantity+? WHERE id=? AND org_id=?',[quantity,materialId,req.user.org_id]);await connection.execute("INSERT INTO movements (material_id,type,quantity,responsible,reason,notes) VALUES (?, 'entrada', ?, ?, 'maintenance_return', ?)",[materialId,quantity,req.user.email,`work_order:${orderId}`]);await connection.commit();res.status(201).json({work_order_id:orderId,material_id:materialId,quantity});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao devolver material'});}finally{connection.release();}});
router.post('/work-orders/:id/labor', write, async (req,res)=>{const orderId=Number(req.params.id),body=req.body||{},hours=body.hours,rate=body.hourly_rate;if(!Number.isSafeInteger(orderId)||orderId<1||typeof hours!=='number'||!Number.isFinite(hours)||hours<=0||hours>10000||typeof rate!=='number'||!Number.isFinite(rate)||rate<0||rate>100000||(body.remarks!==undefined&&(typeof body.remarks!=='string'||body.remarks.length>500)))return res.status(400).json({error:'Apontamento de mão de obra inválido'});try{const [order]=await pool.execute('SELECT id,status FROM maintenance_work_orders WHERE id=? AND org_id=?',[orderId,req.user.org_id]);if(!order.length)return res.status(404).json({error:'Ordem não encontrada'});if(['completed','cancelled'].includes(order[0].status))return res.status(409).json({error:'Ordem encerrada'});const cost=Number((hours*rate).toFixed(2));const [created]=await pool.execute('INSERT INTO work_order_labor (org_id,work_order_id,user_id,hours,hourly_rate,labor_cost,remarks,created_by) VALUES (?,?,?,?,?,?,?,?)',[req.user.org_id,orderId,Number.isSafeInteger(body.user_id)?body.user_id:req.user.id,hours,rate,cost,body.remarks?.trim()||null,req.user.id]);res.status(201).json({id:created.insertId,hours,hourly_rate:rate,labor_cost:cost});}catch(_){res.status(500).json({error:'Erro ao apontar mão de obra'});}});
router.post('/work-orders/:id/reservations', write, async (req,res)=>{const orderId=Number(req.params.id),materialId=req.body?.material_id,quantity=req.body?.quantity;if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<0.001||Math.abs(quantity*1000-Math.round(quantity*1000))>0.000001||quantity>100000)return res.status(400).json({error:'Reserva inválida'});const connection=await pool.getConnection();try{await connection.beginTransaction();const [wo]=await connection.execute('SELECT id,status FROM maintenance_work_orders WHERE id=? AND org_id=? FOR UPDATE',[orderId,req.user.org_id]);if(!wo.length||['completed','cancelled'].includes(wo[0].status)){await connection.rollback();return res.status(409).json({error:'Ordem não disponível para reserva'});}const [mat]=await connection.execute('SELECT id,quantity FROM materials WHERE id=? AND org_id=? AND is_active=1 FOR UPDATE',[materialId,req.user.org_id]);if(!mat.length){await connection.rollback();return res.status(404).json({error:'Material não encontrado'});}const [reserved]=await connection.execute("SELECT COALESCE(SUM(quantity),0) AS quantity FROM inventory_reservations WHERE org_id=? AND material_id=? AND work_order_id<>? AND status='active' FOR UPDATE",[req.user.org_id,materialId,orderId]);if(Number(mat[0].quantity)-Number(reserved[0].quantity)<quantity){await connection.execute("INSERT INTO purchase_requisitions (org_id,work_order_id,material_id,requested_quantity,reason,created_by) VALUES (?,?,?,?, 'maintenance_reservation_shortage', ?) ON DUPLICATE KEY UPDATE requested_quantity=GREATEST(requested_quantity,VALUES(requested_quantity)),status='draft'",[req.user.org_id,orderId,materialId,quantity,req.user.id]);await connection.commit();return res.status(409).json({error:'Saldo disponível insuficiente; requisição criada'});}await connection.execute("INSERT INTO inventory_reservations (org_id,work_order_id,material_id,quantity,created_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity),status='active',created_by=VALUES(created_by)",[req.user.org_id,orderId,materialId,quantity,req.user.id]);await connection.commit();res.status(201).json({work_order_id:orderId,material_id:materialId,quantity,status:'active'});}catch(_){await connection.rollback();res.status(500).json({error:'Erro ao reservar material'});}finally{connection.release();}});
router.delete('/work-orders/:id/reservations/:materialId', write, async (req,res)=>{const orderId=Number(req.params.id),materialId=Number(req.params.materialId);if(!Number.isSafeInteger(orderId)||orderId<1||!Number.isSafeInteger(materialId)||materialId<1)return res.status(400).json({error:'Reserva inválida'});try{const [result]=await pool.execute("UPDATE inventory_reservations SET status='cancelled' WHERE work_order_id=? AND material_id=? AND org_id=? AND status='active'",[orderId,materialId,req.user.org_id]);if(!result.affectedRows)return res.status(404).json({error:'Reserva ativa não encontrada'});await pool.execute('INSERT INTO work_order_audit (org_id,work_order_id,action,detail,actor_id) VALUES (?,?,?,?,?)',[req.user.org_id,orderId,'reservation_cancelled',String(materialId),req.user.id]);res.json({work_order_id:orderId,material_id:materialId,status:'cancelled'});}catch(_){res.status(500).json({error:'Erro ao cancelar reserva'});}});
router.get('/reliability/failure-codes', async(req,res)=>{try{const [rows]=await pool.execute('SELECT id,code,name,category,is_active FROM failure_classifications WHERE org_id=? ORDER BY category,code',[req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar classificações de falha'});}});
router.post('/reliability/failure-codes', requireRoles('superadmin','admin','manager'), async(req,res)=>{const b=req.body||{};if(!text(b.code,50)||!text(b.name,200)||!['symptom','mechanism','cause'].includes(b.category))return res.status(400).json({error:'Classificação inválida'});try{const [created]=await pool.execute('INSERT INTO failure_classifications (org_id,code,name,category,created_by) VALUES (?,?,?,?,?)',[req.user.org_id,b.code.trim(),b.name.trim(),b.category,req.user.id]);res.status(201).json({id:created.insertId,code:b.code.trim(),name:b.name.trim(),category:b.category,is_active:1});}catch(error){res.status(error.code==='ER_DUP_ENTRY'?409:500).json({error:error.code==='ER_DUP_ENTRY'?'Código já cadastrado':'Erro ao cadastrar classificação'});}});
router.patch('/reliability/failure-codes/:id', requireRoles('superadmin','admin','manager'), async(req,res)=>{const id=Number(req.params.id),name=req.body?.name,active=req.body?.is_active;if(!Number.isSafeInteger(id)||id<1||(name===undefined&&active===undefined)||(name!==undefined&&!text(name,200))||(active!==undefined&&typeof active!=='boolean'))return res.status(400).json({error:'Atualização inválida'});try{const [updated]=await pool.execute('UPDATE failure_classifications SET name=COALESCE(?,name),is_active=COALESCE(?,is_active) WHERE id=? AND org_id=?',[name?.trim()??null,active===undefined?null:(active?1:0),id,req.user.org_id]);if(!updated.affectedRows)return res.status(404).json({error:'Classificação não encontrada'});res.json({id});}catch(_){res.status(500).json({error:'Erro ao atualizar classificação'});}});
router.post('/work-orders/:id/downtime', write, async (req,res)=>{
  const orderId=Number(req.params.id), body=req.body||{}, start=new Date(body.started_at), end=new Date(body.ended_at);
  if(!Number.isSafeInteger(orderId)||orderId<1||Number.isNaN(start.getTime())||Number.isNaN(end.getTime())||end.getTime()<=start.getTime()||!text(body.failure_symptom,200))return res.status(400).json({error:'Registro de downtime inválido'});
  if((body.failure_mechanism!==undefined&&(typeof body.failure_mechanism!=='string'||body.failure_mechanism.length>200))||(body.remarks!==undefined&&(typeof body.remarks!=='string'||body.remarks.length>5000)))return res.status(400).json({error:'Dados de falha inválidos'});
  const causingMaterial=body.causing_material_id===undefined||body.causing_material_id===null?null:Number(body.causing_material_id);
  if(causingMaterial!==null&&(!Number.isSafeInteger(causingMaterial)||causingMaterial<1))return res.status(400).json({error:'Material causador inválido'});
  const classificationId=body.failure_classification_id==null?null:Number(body.failure_classification_id);
  if(classificationId!==null&&(!Number.isSafeInteger(classificationId)||classificationId<1))return res.status(400).json({error:'Classificação de falha inválida'});
  const c=await pool.getConnection();try{await c.beginTransaction();const [orders]=await c.execute('SELECT wo.id,wo.asset_id,wo.financial_closed_at,a.hourly_downtime_cost FROM maintenance_work_orders wo JOIN assets a ON a.id=wo.asset_id AND a.org_id=wo.org_id WHERE wo.id=? AND wo.org_id=? FOR UPDATE',[orderId,req.user.org_id]);if(!orders.length){await c.rollback();return res.status(404).json({error:'Ordem não encontrada'});}if(orders[0].financial_closed_at){await c.rollback();return res.status(409).json({error:'Ordem fechada financeiramente'});}if(causingMaterial!==null){const [material]=await c.execute('SELECT id FROM materials WHERE id=? AND org_id=?',[causingMaterial,req.user.org_id]);if(!material.length){await c.rollback();return res.status(404).json({error:'Material causador não encontrado'});}}if(classificationId!==null){const [classification]=await c.execute('SELECT id FROM failure_classifications WHERE id=? AND org_id=? AND is_active=1',[classificationId,req.user.org_id]);if(!classification.length){await c.rollback();return res.status(404).json({error:'Classificação não encontrada'});}}const hours=(end.getTime()-start.getTime())/3600000,cost=Number(orders[0].hourly_downtime_cost)||0,loss=Number((hours*cost).toFixed(2));const [created]=await c.execute('INSERT INTO downtime_records (org_id,work_order_id,asset_id,started_at,ended_at,downtime_hours,hourly_cost,production_loss_cost,failure_symptom,failure_mechanism,causing_material_id,remarks,created_by,failure_classification_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,orderId,orders[0].asset_id,start,end,hours,cost,loss,body.failure_symptom.trim(),body.failure_mechanism?.trim()||null,causingMaterial,body.remarks?.trim()||null,req.user.id,classificationId]);await c.commit();res.status(201).json({id:created.insertId,downtime_hours:hours,production_loss_cost:loss});}catch(_){await c.rollback();res.status(500).json({error:'Erro ao registrar downtime'});}finally{c.release();}
});
router.get('/work-orders/:id/downtime', async (req,res)=>{const orderId=Number(req.params.id);if(!Number.isSafeInteger(orderId)||orderId<1)return res.status(400).json({error:'Ordem inválida'});try{const [rows]=await pool.execute('SELECT d.*,m.code AS causing_material_code,fc.code AS failure_code,fc.name AS failure_name FROM downtime_records d LEFT JOIN materials m ON m.id=d.causing_material_id AND BINARY m.org_id=BINARY d.org_id LEFT JOIN failure_classifications fc ON fc.id=d.failure_classification_id AND BINARY fc.org_id=BINARY d.org_id WHERE d.work_order_id=? AND d.org_id=? ORDER BY d.started_at DESC',[orderId,req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar downtime'});}});
router.get('/reliability/assets/:id', async (req,res)=>{
  const assetId=Number(req.params.id), from=req.query.from?new Date(req.query.from):new Date(Date.now()-30*86400000), to=req.query.to?new Date(req.query.to):new Date();
  if(!Number.isSafeInteger(assetId)||assetId<1||!Number.isFinite(+from)||!Number.isFinite(+to)||to<=from||to-from>3650*86400000)return res.status(400).json({error:'Período ou ativo inválido'});
  try{
    const [asset]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);
    if(!asset.length)return res.status(404).json({error:'Ativo não encontrado'});
    const [rows]=await pool.execute("SELECT d.started_at,d.ended_at,d.work_order_id,d.production_loss_cost,wo.type FROM downtime_records d JOIN maintenance_work_orders wo ON wo.id=d.work_order_id AND BINARY wo.org_id=BINARY d.org_id WHERE d.org_id=? AND d.asset_id=? AND d.started_at<? AND (d.ended_at>? OR d.ended_at IS NULL) ORDER BY d.started_at LIMIT 10001",[req.user.org_id,assetId,to,from]);
    if(rows.length>10000)return res.status(422).json({error:'Reduza o período: limite de registros para análise excedido.'});
    const [observations]=await pool.execute('SELECT kind,'+qualifiedObservations.utcColumns+' FROM asset_observations WHERE org_id=? AND asset_id=? AND started_at<? AND ended_at>? ORDER BY started_at LIMIT 4001',[req.user.org_id,assetId,qualifiedObservations.sqlTime(to),qualifiedObservations.sqlTime(from)]);
    if(observations.length>4000)return res.status(422).json({error:'Reduza o período: limite de observações excedido.'});
    const report=qualifiedObservations.report({from,to,rows,observations});
    const [materials]=await pool.execute('SELECT COALESCE(SUM(wom.material_cost),0) AS material_cost FROM work_order_materials wom JOIN maintenance_work_orders wo ON wo.id=wom.work_order_id AND BINARY wo.org_id=BINARY wom.org_id WHERE wom.org_id=? AND wo.asset_id=? AND wom.issued_at>=? AND wom.issued_at<?',[req.user.org_id,assetId,from,to]);
    const [waiting]=await pool.execute("SELECT COUNT(*) AS completed_waits,AVG(TIMESTAMPDIFF(SECOND,pr.created_at,po.received_at))/3600 AS mtws_hours FROM purchase_requisitions pr JOIN maintenance_work_orders wo ON wo.id=pr.work_order_id AND BINARY wo.org_id=BINARY pr.org_id JOIN maintenance_purchase_orders po ON po.requisition_id=pr.id AND BINARY po.org_id=BINARY pr.org_id WHERE pr.org_id=? AND wo.asset_id=? AND po.received_at IS NOT NULL AND pr.created_at>=? AND po.received_at<?",[req.user.org_id,assetId,from,to]);
    const materialCost=Number(materials[0].material_cost);
    res.json({...report,period:{from:from.toISOString(),to:to.toISOString(),hours:(to-from)/3600000},mtws_hours:waiting[0].mtws_hours==null?null:Number(waiting[0].mtws_hours),completed_material_waits:Number(waiting[0].completed_waits),material_cost:materialCost,tco:report.production_loss_cost+materialCost});
  }catch(_){res.status(500).json({error:'Erro ao calcular confiabilidade'});}
});
router.get('/reliability/summary', async(req,res)=>{
  const from=req.query.from?new Date(req.query.from):new Date(Date.now()-30*86400000),to=req.query.to?new Date(req.query.to):new Date();
  if(!Number.isFinite(+from)||!Number.isFinite(+to)||to<=from||to-from>3650*86400000)return res.status(400).json({error:'Período inválido'});
  try{
    const [assets]=await pool.execute('SELECT id,asset_code,name,status FROM assets WHERE org_id=? ORDER BY asset_code LIMIT 501',[req.user.org_id]);
    if(assets.length>500)return res.status(422).json({error:'Limite de equipamentos para comparação excedido.'});
    const [rows]=await pool.execute("SELECT d.asset_id,d.started_at,d.ended_at,d.work_order_id,d.production_loss_cost,wo.type FROM downtime_records d JOIN maintenance_work_orders wo ON wo.id=d.work_order_id AND BINARY wo.org_id=BINARY d.org_id WHERE d.org_id=? AND d.started_at<? AND (d.ended_at>? OR d.ended_at IS NULL) ORDER BY d.asset_id,d.started_at LIMIT 10001",[req.user.org_id,to,from]);
    if(rows.length>10000)return res.status(422).json({error:'Reduza o período: limite de registros para análise excedido.'});
    const groups=new Map();for(const row of rows){const key=String(row.asset_id);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}
    const [observations]=await pool.execute('SELECT asset_id,kind,'+qualifiedObservations.utcColumns+' FROM asset_observations WHERE org_id=? AND started_at<? AND ended_at>? ORDER BY asset_id,started_at LIMIT 4001',[req.user.org_id,qualifiedObservations.sqlTime(to),qualifiedObservations.sqlTime(from)]);
    if(observations.length>4000)return res.status(422).json({error:'Reduza o período: limite de observações excedido.'});
    const observed=new Map();for(const record of observations){const key=String(record.asset_id);if(!observed.has(key))observed.set(key,[]);observed.get(key).push(record);}
    res.json({period:{from:from.toISOString(),to:to.toISOString(),hours:(to-from)/3600000},assets:assets.map(asset=>({...asset,...qualifiedObservations.report({from,to,rows:groups.get(String(asset.id))||[],observations:observed.get(String(asset.id))||[]})})),limit:500});
  }catch(_){res.status(500).json({error:'Erro ao consolidar confiabilidade'});}
});
router.get('/plans', async (req,res)=>{try{const [rows]=await pool.execute('SELECT p.*,a.asset_code,a.name AS asset_name FROM preventive_plans p JOIN assets a ON a.id=p.asset_id AND a.org_id=p.org_id WHERE p.org_id=? ORDER BY p.next_due_at',[req.user.org_id]);res.json(rows);}catch(_){res.status(500).json({error:'Erro ao buscar planos'});}});
router.get('/assets/:id/counters', async(req,res)=>{const assetId=Number(req.params.id);if(!Number.isSafeInteger(assetId)||assetId<1)return res.status(400).json({error:'Ativo inválido'});try{const [assets]=await pool.execute('SELECT id,operating_hours,operating_cycles FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);if(!assets.length)return res.status(404).json({error:'Ativo não encontrado'});const [readings]=await pool.execute('SELECT operating_hours,operating_cycles,recorded_by,recorded_at FROM asset_counter_readings WHERE asset_id=? AND org_id=? ORDER BY id DESC LIMIT 50',[assetId,req.user.org_id]);res.json({asset:assets[0],readings});}catch(_){res.status(500).json({error:'Erro ao buscar contadores'});}});
router.post('/assets/:id/counters', write, async(req,res)=>{const assetId=Number(req.params.id),hours=req.body?.operating_hours,cycles=req.body?.operating_cycles,valid=value=>value===undefined||(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=1000000000);if(!Number.isSafeInteger(assetId)||assetId<1||(hours===undefined&&cycles===undefined)||!valid(hours)||!valid(cycles))return res.status(400).json({error:'Leitura de contador inválida'});const connection=await pool.getConnection();let nextHours,nextCycles;try{await connection.beginTransaction();const [assets]=await connection.execute('SELECT operating_hours,operating_cycles FROM assets WHERE id=? AND org_id=? FOR UPDATE',[assetId,req.user.org_id]);if(!assets.length){await connection.rollback();return res.status(404).json({error:'Ativo não encontrado'});}nextHours=hours??Number(assets[0].operating_hours);nextCycles=cycles??Number(assets[0].operating_cycles);if(nextHours<Number(assets[0].operating_hours)||nextCycles<Number(assets[0].operating_cycles)){await connection.rollback();return res.status(409).json({error:'Contador não pode retroceder'});}await connection.execute('UPDATE assets SET operating_hours=?,operating_cycles=? WHERE id=? AND org_id=?',[nextHours,nextCycles,assetId,req.user.org_id]);await connection.execute('INSERT INTO asset_counter_readings (org_id,asset_id,operating_hours,operating_cycles,recorded_by) VALUES (?,?,?,?,?)',[req.user.org_id,assetId,nextHours,nextCycles,req.user.id]);await connection.commit();}catch(_){await connection.rollback();return res.status(500).json({error:'Erro ao registrar contador'});}finally{connection.release();}try{const generated=await generateDuePreventives(req.user.org_id,req.user.id);res.status(201).json({asset_id:assetId,operating_hours:nextHours,operating_cycles:nextCycles,generated});}catch(_){res.status(201).json({asset_id:assetId,operating_hours:nextHours,operating_cycles:nextCycles,generated:[],scheduler_pending:true});}});
router.get('/plans/overview', async (req,res)=>{
  const month=req.query.month, assetId=req.query.asset_id===undefined?null:Number(req.query.asset_id);
  if(typeof month!=='string'||!/^20\d{2}-(0[1-9]|1[0-2])$/.test(month)||(assetId!==null&&(!Number.isSafeInteger(assetId)||assetId<1)))return res.status(400).json({error:'Período ou ativo inválido'});
  const from=`${month}-01`,to=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),1)).toISOString().slice(0,10);
  try{
    if(assetId!==null){const [assets]=await pool.execute('SELECT id FROM assets WHERE id=? AND org_id=?',[assetId,req.user.org_id]);if(!assets.length)return res.status(404).json({error:'Ativo não encontrado'});}
    const [stats]=await pool.execute("SELECT p.id AS plan_id,p.asset_id,COUNT(r.id) AS generated_count,COALESCE(SUM(CASE WHEN wo.status='completed' THEN 1 ELSE 0 END),0) AS completed_count FROM preventive_plans p LEFT JOIN preventive_plan_runs r ON r.plan_id=p.id AND r.org_id=p.org_id LEFT JOIN maintenance_work_orders wo ON wo.id=r.work_order_id AND wo.org_id=p.org_id WHERE p.org_id=? AND (? IS NULL OR p.asset_id=?) GROUP BY p.id,p.asset_id",[req.user.org_id,assetId,assetId]);
    const [runs]=await pool.execute("SELECT r.plan_id,p.asset_id,DATE_FORMAT(r.due_date,'%Y-%m-%d') AS due_date,wo.id AS work_order_id,wo.status AS work_order_status,DATE_FORMAT(wo.completed_at,'%Y-%m-%d') AS completed_date FROM preventive_plan_runs r JOIN preventive_plans p ON p.id=r.plan_id AND p.org_id=r.org_id LEFT JOIN maintenance_work_orders wo ON wo.id=r.work_order_id AND wo.org_id=r.org_id WHERE r.org_id=? AND r.due_date>=? AND r.due_date<? AND (? IS NULL OR p.asset_id=?) ORDER BY r.due_date,r.id",[req.user.org_id,from,to,assetId,assetId]);
    res.json({stats,runs});
  }catch(_){res.status(500).json({error:'Erro ao buscar indicadores preventivos'});}
});
router.post('/plans', write, async (req,res)=>{
  const assetId=Number(req.body?.asset_id),title=req.body?.title,days=req.body?.interval_days,next=req.body?.next_due_at,tasks=req.body?.tasks??[];
  const intervalHours=req.body?.interval_hours??null,intervalCycles=req.body?.interval_cycles??null;
  const validDate=typeof next==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(next)&&!Number.isNaN(Date.parse(`${next}T00:00:00Z`))&&new Date(`${next}T00:00:00Z`).toISOString().slice(0,10)===next;
  const validCounter=value=>value===null||(typeof value==='number'&&Number.isFinite(value)&&value>0&&value<=1000000000);
  if(!Number.isSafeInteger(assetId)||assetId<1||!text(title,200)||!Number.isSafeInteger(days)||days<1||days>3650||!validDate||!validCounter(intervalHours)||!validCounter(intervalCycles)||!Array.isArray(tasks)||tasks.length>50||tasks.some(task=>!text(task,300)))return res.status(400).json({error:'Plano preventivo inválido'});
  const priority=req.body?.priority||'medium';let calendar;try{calendar=Calendar.validate(req.body?.calendar);}catch(e){return res.status(400).json({error:e.message});}if(!['urgent','high','medium','low'].includes(priority))return res.status(400).json({error:'Prioridade inválida'});
  const connection=await pool.getConnection();try{await connection.beginTransaction();const [assets]=await connection.execute('SELECT id,operating_hours,operating_cycles FROM assets WHERE id=? AND org_id=? FOR UPDATE',[assetId,req.user.org_id]);if(!assets.length){await connection.rollback();return res.status(404).json({error:'Ativo não encontrado'});}const nextHours=intervalHours===null?null:Number(assets[0].operating_hours)+intervalHours,nextCycles=intervalCycles===null?null:Number(assets[0].operating_cycles)+intervalCycles;const [created]=await connection.execute('INSERT INTO preventive_plans (org_id,asset_id,title,interval_days,next_due_at,interval_hours,interval_cycles,next_due_hours,next_due_cycles,created_by,priority,calendar_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.org_id,assetId,title.trim(),days,next,intervalHours,intervalCycles,nextHours,nextCycles,req.user.id,priority,calendar?JSON.stringify(calendar):null]);for(const [index,task] of tasks.entries())await connection.execute('INSERT INTO preventive_plan_tasks (org_id,plan_id,title,position_order) VALUES (?,?,?,?)',[req.user.org_id,created.insertId,task.trim(),index]);await connection.commit();res.status(201).json({id:created.insertId,asset_id:assetId,title:title.trim(),interval_days:days,next_due_at:next,interval_hours:intervalHours,interval_cycles:intervalCycles,next_due_hours:nextHours,next_due_cycles:nextCycles,task_count:tasks.length,active:1});}catch(error){await connection.rollback();res.status(error.code==='ER_DUP_ENTRY'?409:500).json({error:error.code==='ER_DUP_ENTRY'?'Plano já existe':'Erro ao criar plano'});}finally{connection.release();}
});
